from datetime import date

# Orders the agent can see after the customer is verified (normally from the order API)
ORDERS = {
    "T-10442": {"customer": "c-881", "total": 89.00, "delivered": date(2026, 9, 2)},
    "T-10501": {"customer": "c-881", "total": 420.00, "delivered": date(2026, 9, 20)},
    "T-09987": {"customer": "c-305", "total": 35.00, "delivered": date(2026, 7, 1)},
}
AUTO_LIMIT = 150.00      # above this, a human approves
WINDOW_DAYS = 30         # returns policy v7, section 2

def issue_refund(verified_customer, order_id, amount, today=date(2026, 9, 28)):
    """The action the model may call. Policy is enforced HERE, not in the prompt."""
    order = ORDERS.get(order_id)
    if order is None or order["customer"] != verified_customer:
        return {"status": "refused", "reason": "order not found for this customer"}
    if (today - order["delivered"]).days > WINDOW_DAYS:
        return {"status": "refused", "reason": "outside the 30-day window"}
    if amount > order["total"]:
        return {"status": "refused", "reason": "more than the order total"}
    if amount > AUTO_LIMIT:
        return {"status": "needs_human", "reason": f"over the {AUTO_LIMIT:.0f} auto limit"}
    return {"status": "refunded", "amount": amount}

print(issue_refund("c-881", "T-10442", 89.00))
print(issue_refund("c-881", "T-10501", 420.00))
print(issue_refund("c-881", "T-09987", 35.00))   # someone else's order
# Output:
# {'status': 'refunded', 'amount': 89.0}
# {'status': 'needs_human', 'reason': 'over the 150 auto limit'}
# {'status': 'refused', 'reason': 'order not found for this customer'}
